import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const response = await member.post("/api/auth/logout");
  const receivedAt = Date.now();

  // Assert
  await expectStatus(response, 204);
  const cookie = response
    .headersArray()
    .find((h) => h.name.toLowerCase() === "set-cookie" && /^session=/.test(h.value));
  expect(cookie?.value, "logout sends a Set-Cookie for the session cookie").toMatch(/^session=(""|);/);
  expect(cookie?.value.toLowerCase(), "the session cookie expires immediately").toContain("max-age=0");
  const expires = Date.parse(/expires=([^;]+)/i.exec(cookie?.value ?? "")?.[1] ?? "");
  expect(expires, `the session cookie's expiry is not in the future: ${cookie?.value}`).toBeLessThanOrEqual(receivedAt);
});
